fn lookup(&self, data: &str, fired: &mut BTreeSet<String>) -> String {
    for rule in &self.rules {
        if rule.matches(data) {
            fired.insert(rule.id.clone());
            if let Some(hint) = self.answer(rule, data, fired) {
                return hint;
            }
        }
    }
    self.fallback.clone()
}

